class Solution {
public:
    int characterReplacement(string s, int k) {
        map<char, int> cnt;
        int l = 0, most = 0, best = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            most = max(most, ++cnt[s[r]]);
            while (r - l + 1 - most > k) {
                cnt[s[l]]--;
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};
